WITH store_agg AS (SELECT ss.ss_sold_date_sk AS date_sk, SUM(ss.ss_net_profit) AS store_profit, AVG(hd.hd_vehicle_count) AS avg_vehicle_count, MIN(td.t_hour) AS earliest_hour FROM store_sales ss JOIN household_demographics hd ON ss.ss_hdemo_sk = hd.hd_demo_sk JOIN time_dim td ON ss.ss_sold_time_sk = td.t_time_sk GROUP BY ss.ss_sold_date_sk), web_agg AS (SELECT ws.ws_sold_date_sk AS date_sk, SUM(ws.ws_net_profit) AS web_profit, MIN(td.t_hour) AS earliest_hour FROM web_sales ws JOIN time_dim td ON ws.ws_sold_time_sk = td.t_time_sk GROUP BY ws.ws_sold_date_sk) SELECT COALESCE(s.date_sk, w.date_sk) AS date_sk, s.store_profit, w.web_profit, COALESCE(s.store_profit, 0) - COALESCE(w.web_profit, 0) AS profit_diff, CASE WHEN COALESCE(s.store_profit, 0) > COALESCE(w.web_profit, 0) THEN 'StoreHigher' ELSE 'WebHigher' END AS higher_channel, DENSE_RANK() OVER (ORDER BY ABS(COALESCE(s.store_profit, 0) - COALESCE(w.web_profit, 0)) DESC) AS diff_rank, s.avg_vehicle_count, s.earliest_hour, w.earliest_hour AS web_earliest_hour FROM store_agg s FULL OUTER JOIN web_agg w ON s.date_sk = w.date_sk ORDER BY diff_rank
